<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, shallowRef, watch } from 'vue'
import { ART_CATEGORIES, type ArtCategory } from '../domain/project-art-spec'
import { copyWorkbench, needOutputSize, needsReview, validateWorkbenchSpec, validWorkbenchSize, workbenchLabels, readWorkbenchReferenceUploads, rememberWorkbenchReferenceUpload, releaseRejectedWorkbenchReferenceUpload, workbenchReferenceScopeKey, legacyWorkbenchUploadUnknown, type WorkbenchNeed, type WorkbenchSpec, type WorkbenchReference, type WorkbenchReferenceScope, type WorkbenchReferenceUpload } from '../domain/art-workbench'
import { prepareLocalReference, decodeAiReferenceUploadReceipt, AiReferenceUploadError, type PreparedLocalReference } from '../domain/ai-reference-upload'
import { aiReferenceUploadProvider } from '../ai-reference-upload-integration'
import { aiResourceReadProvider } from '../ai-resource-read-integration'
import { useArtWorkbenchStore } from '../stores/art-workbench'
import { useProjectArtSpecStore } from '../stores/project-art-spec'
import { useRegisteredProjectStore } from '../stores/registered-project'
import { createWorkbenchProvider } from '../adapters/art-workbench'
import { aiJobsReadProvider } from '../ai-jobs-read-integration'
import type { AiJobSnapshot } from '../domain/ai-jobs-read'
import AiJobsReadPanel from './AiJobsReadPanel.vue'
const taskStep=ref(3)
function chooseStep(index:number){if((activeNeed.value||browsingJobs.value)&&index>=3&&index<=5){taskStep.value=index;emit('stage-change',{step:index,reached:5})}}
defineExpose({chooseStep})
const props=defineProps<{view:'specs'|'needs'}>()
const emit=defineEmits<{'open-references':[];'stage-change':[value:{step:number;reached:number}]}>()
const selection=useRegisteredProjectStore(),normStore=useProjectArtSpecStore(),store=useArtWorkbenchStore()
const transport=createWorkbenchProvider((...args)=>fetch(...args))
watch([()=>selection.project,()=>selection.currentSource],()=>{store.bind(selection.project&&selection.currentSource?{projectId:selection.project.id,projectPath:selection.project.path,source:selection.currentSource}:null,selection.currentSource?transport:null)},{immediate:true,flush:'sync'})
onBeforeUnmount(store.leave)
const norm=computed(()=>normStore.base&&normStore.hash&&normStore.context?.projectId===selection.project?.id&&normStore.context?.projectPath===selection.project?.path&&normStore.context?.source===selection.currentSource&&['editing','saved'].includes(normStore.phase)&&!normStore.dirty&&!normStore.pending&&!normStore.blocked&&normStore.base.projectId===selection.project?.id?{hash:normStore.hash,version:normStore.base.version}:null)
const editable=computed(()=>!!store.draft&&!store.busy&&store.phase==='ready')
const query=ref(''),filter=ref<ArtCategory|''>(''),message=ref('')
const specs=computed(()=>store.draft?.specs.filter(s=>(!filter.value||s.category===filter.value)&&(!query.value||s.name.includes(query.value)||s.id.includes(query.value)))??[])
const needs=computed(()=>store.draft?.needs.filter(n=>(!filter.value||n.spec.category===filter.value)&&(!query.value||n.name.includes(query.value)||n.id.includes(query.value)))??[])
const specEditor=ref<WorkbenchSpec|null>(null),needEditor=ref<WorkbenchNeed|null>(null),originalId=ref<string|null>(null),needCategory=ref<ArtCategory>('icon')
const selectedSpecs=computed(()=>store.draft?.specs.filter(s=>s.category===needCategory.value)??[])
const referencesOpen=ref(false),referenceScope=ref(''),referenceLevel=ref<'project'|'spec'|'asset'>('project')
const shownReferences=computed(()=>referenceLevel.value==='project'?store.draft?.projectReferences??[]:referenceLevel.value==='spec'?specEditor.value?.references??[]:needEditor.value?.references??[])
const referenceNames={project:'项目风格参考：约束整体画风，不覆盖单项内容。',spec:'规格范例：说明构图和形态，不改变项目画风。',asset:'单素材内容参考：说明主体细节，不覆盖固定尺寸。'}
function references(scope:keyof typeof referenceNames){referenceLevel.value=scope;referenceScope.value=referenceNames[scope];referencesOpen.value=true;clearReferenceSelection();loadReferenceRecords()}
function newSpec(spec?:WorkbenchSpec){originalId.value=spec?.id??null;specEditor.value=spec?copyWorkbench(spec):{id:'',name:'',category:'icon',version:1,sizePolicy:'fixed',width:128,height:128,destination:'assets/art/icons',exportDirectory:'art/final/icons',imageOutput:'transparent-png',style:'',references:[]};message.value=''}
function saveSpec(){if(!editable.value||!specEditor.value||!store.draft)return;try{const spec=copyWorkbench(specEditor.value);if(spec.category!=='ui')spec.sizePolicy='fixed';validateWorkbenchSpec(spec);const index=store.draft.specs.findIndex(s=>s.id===originalId.value);if(store.draft.specs.some((s,i)=>s.id===spec.id&&i!==index))throw Error('规格标识已存在');if(index>=0){if(JSON.stringify(spec)===JSON.stringify(store.draft.specs[index])){specEditor.value=null;return}spec.version=(store.base?.specs.find(s=>s.id===spec.id)?.version??0)+1;store.draft.specs[index]=spec}else store.draft.specs.push(spec);specEditor.value=null}catch(e){message.value=(e as Error).message}}
function newNeed(need?:WorkbenchNeed){originalId.value=need?.id??null;needCategory.value=need?.spec.category??'icon';needEditor.value=need?copyWorkbench(need):{id:'',name:'',version:1,content:'',specId:'',specVersion:0,spec:{} as WorkbenchSpec,references:[]};message.value=''}
function chooseSpec(id:string){const spec=store.draft?.specs.find(s=>s.id===id);if(!needEditor.value||!spec)return;needEditor.value.spec=copyWorkbench(spec);needEditor.value.specId=spec.id;needEditor.value.specVersion=spec.version;if(spec.sizePolicy==='per-asset')needEditor.value.size={width:spec.width,height:spec.height};else delete needEditor.value.size}
function saveNeed(){if(!editable.value||!store.draft||!needEditor.value)return;const need=copyWorkbench(needEditor.value);if(!/^[A-Za-z0-9][A-Za-z0-9_-]{0,79}$/.test(need.id)||!need.name.trim()||!need.content.trim()||!need.specId){message.value='请填写标识、名称、规格和内容要求。';return}if(need.spec.sizePolicy==='per-asset'&&(!need.size||!validWorkbenchSize(need.size.width,need.size.height))){message.value='请填写有效的单项尺寸。';return}const index=store.draft.needs.findIndex(n=>n.id===originalId.value);if(store.draft.needs.some((n,i)=>n.id===need.id&&i!==index)){message.value='需求标识已存在';return}if(index>=0){if(store.draft.needs[index]!.jobId){message.value='已绑定任务的需求不可编辑。';return}if(JSON.stringify(need)===JSON.stringify(store.draft.needs[index])){needEditor.value=null;return}need.version=(store.base?.needs.find(n=>n.id===need.id)?.version??0)+1;store.draft.needs[index]=need}else store.draft.needs.push(need);needEditor.value=null}
function reviewNeed(need:WorkbenchNeed){if(!editable.value||need.jobId||!store.draft)return;const spec=store.draft.specs.find(s=>s.id===need.specId);if(spec){need.version=(store.base?.needs.find(n=>n.id===need.id)?.version??0)+1;need.spec=copyWorkbench(spec);need.specVersion=spec.version;if(spec.sizePolicy==='per-asset')need.size??={width:spec.width,height:spec.height};else delete need.size}}
const browsingJobs=ref(false)
function browseJobs(){browsingJobs.value=true;activeNeed.value=null;taskStep.value=3;emit('stage-change',{step:3,reached:5})}
const binding=ref<WorkbenchNeed|null>(null),jobs=ref<AiJobSnapshot[]>([]),jobsBusy=ref(false),jobId=ref(''),activeNeed=ref<WorkbenchNeed|null>(null),jobsPanel=ref<InstanceType<typeof AiJobsReadPanel>|null>(null)
let jobsEpoch=0
watch(()=>store.context,()=>{jobsEpoch++;binding.value=null;jobs.value=[];jobsBusy.value=false;activeNeed.value=null;browsingJobs.value=false;specEditor.value=null;needEditor.value=null;message.value='';query.value='';filter.value='';emit('stage-change',{step:props.view==='specs'?1:2,reached:2})},{flush:'sync'})
async function openBinding(need:WorkbenchNeed){binding.value=need;jobId.value=need.jobId??'';jobs.value=[];const target=selection.project,source=selection.currentSource,reader=aiJobsReadProvider.value;if(!target||!source||!reader)return;const token=++jobsEpoch;jobsBusy.value=true;try{const result=await reader.readJobs(target.id);if(token===jobsEpoch&&selection.project?.id===target.id&&selection.project.path===target.path&&selection.currentSource===source&&reader===aiJobsReadProvider.value)jobs.value=result.jobs}catch{if(token===jobsEpoch)message.value='现有任务读取失败，请关闭后重试。'}finally{if(token===jobsEpoch)jobsBusy.value=false}}
async function bindJob(){if(!editable.value||!binding.value||!jobs.value.some(j=>j.jobId===jobId.value)||!store.draft)return;const need=store.draft.needs.find(n=>n.id===binding.value!.id);if(!need||need.jobId)return;need.jobId=jobId.value;need.version=(store.base?.needs.find(n=>n.id===need.id)?.version??0)+1;await store.save();if(store.phase==='ready'&&!store.dirty)binding.value=null}
async function openJob(need:WorkbenchNeed){const target=selection.project,source=selection.currentSource,reader=aiJobsReadProvider.value;if(!target||!source||!reader||!need.jobId)return;const token=++jobsEpoch;browsingJobs.value=false;taskStep.value=3;activeNeed.value=need;emit('stage-change',{step:3,reached:5});await nextTick();try{const result=await reader.readJobs(target.id);const snapshot=result.jobs.find(j=>j.jobId===need.jobId);if(token===jobsEpoch&&selection.project?.id===target.id&&selection.currentSource===source&&reader===aiJobsReadProvider.value&&snapshot)await jobsPanel.value?.readCreatedTask({snapshot,project:target,source,jobsReader:reader});else if(token===jobsEpoch)message.value='该任务尚未在当前工程回读中找到。'}catch{if(token===jobsEpoch)message.value='绑定任务读取失败，请重试。'}}
function closeJob(){activeNeed.value=null;browsingJobs.value=false;emit('stage-change',{step:2,reached:2})}

// Only file receipts and identity metadata are retained; source bytes stay in this dialog.
const referenceSelected=shallowRef<PreparedLocalReference|null>(null),referenceFileName=ref(''),referenceLocalShown=ref(false),referenceConfirmed=ref(false),referencePreparing=ref(false),referenceUploading=ref(false),referenceError=ref(''),referenceStorageBlocked=ref(false)
const referenceRecords=ref<WorkbenchReferenceUpload[]>([]),referencePreview=ref<{base64:string;sha256:string;width:number;height:number}|null>(null),referencePreviewBusy=ref(false)
let referenceEpoch=0,referencePreviewEpoch=0
const referenceTarget=computed(()=>referenceLevel.value==='project'?store.draft:referenceLevel.value==='spec'?specEditor.value:needEditor.value)
const referenceIdentity=computed<WorkbenchReferenceScope|null>(()=>{
 const target=selection.project,id=referenceLevel.value==='project'?target?.id:referenceTarget.value&&'id' in referenceTarget.value?referenceTarget.value.id:''
 return target&&selection.currentSource&&id&&/^[A-Za-z0-9][A-Za-z0-9_-]{0,79}$/.test(id)?{projectId:target.id,projectPath:target.path,scope:referenceLevel.value==='asset'?'need':referenceLevel.value,targetId:id}:null
})
const referenceWritable=computed(()=>editable.value&&!!referenceIdentity.value&&!!referenceTarget.value&&!(referenceLevel.value==='asset'&&needEditor.value?.jobId))
const referenceLocalUrl=computed(()=>referenceSelected.value?'data:'+referenceSelected.value.mimeType+';base64,'+referenceSelected.value.base64:'')
const scopeRecords=computed(()=>referenceIdentity.value?referenceRecords.value.filter(row=>workbenchReferenceScopeKey(row)===workbenchReferenceScopeKey(referenceIdentity.value!)):[])
const referenceCanUpload=computed(()=>referenceWritable.value&&!!aiReferenceUploadProvider.value&&!!store.capabilities?.referenceUpload&&!!referenceSelected.value?.pixelDecoded&&referenceLocalShown.value&&referenceConfirmed.value&&!referencePreparing.value&&!referenceUploading.value&&!referenceStorageBlocked.value&&shownReferences.value.length<4)
function referenceStorage(){return globalThis.sessionStorage}
function loadReferenceRecords(){try{referenceRecords.value=readWorkbenchReferenceUploads(referenceStorage());referenceStorageBlocked.value=false}catch{referenceStorageBlocked.value=true;referenceError.value='无法可靠读取上传恢复记录，已停止上传。原有引用保留。'}}
function clearReferenceSelection(){referenceEpoch++;referenceSelected.value=null;referenceFileName.value='';referenceLocalShown.value=false;referenceConfirmed.value=false;referencePreparing.value=false;referencePreviewEpoch++;referencePreview.value=null;referencePreviewBusy.value=false;referenceError.value=''}
watch([()=>store.context,aiReferenceUploadProvider,aiResourceReadProvider],()=>{clearReferenceSelection();referencesOpen.value=false},{flush:'sync'})
watch([referenceTarget,referenceIdentity],()=>{referenceConfirmed.value=false;referencePreviewEpoch++;referencePreview.value=null},{flush:'sync'})
watch(referencesOpen,open=>{if(!open)clearReferenceSelection()})
async function chooseReferenceFile(file:File|undefined){
 if(!file||!referenceWritable.value||referenceUploading.value)return
 clearReferenceSelection();const token=referenceEpoch,target=referenceTarget.value,identity=referenceIdentity.value&&workbenchReferenceScopeKey(referenceIdentity.value),source=selection.currentSource
 referencePreparing.value=true
 try{
  const selected=await prepareLocalReference(file,{decode:async blob=>{if(typeof createImageBitmap!=='function')throw Error('decode-unavailable');const bitmap=await createImageBitmap(blob);try{return {width:bitmap.width,height:bitmap.height}}finally{bitmap.close()}}})
  if(token!==referenceEpoch||target!==referenceTarget.value||source!==selection.currentSource||!referenceIdentity.value||identity!==workbenchReferenceScopeKey(referenceIdentity.value))return
  referenceSelected.value=selected;referenceFileName.value=(file.name||'参考图').slice(0,240);loadReferenceRecords()
  if(referenceRecords.value.some(row=>row.projectId===referenceIdentity.value!.projectId&&row.projectPath===referenceIdentity.value!.projectPath&&row.originalSha256===selected.sha256&&row.receipt===null)||legacyWorkbenchUploadUnknown(referenceStorage(),referenceIdentity.value.projectId,selected.sha256)){referenceStorageBlocked.value=true;referenceError.value='此文件存在结果未知的上传记录，请先回原工程和原层核对；未重新上传。'}
 }catch(error){if(token===referenceEpoch){referenceError.value=error instanceof AiReferenceUploadError?error.message:'本地图片解码或上传恢复记录校验失败，未上传。';referenceSelected.value=null}}
 finally{if(token===referenceEpoch)referencePreparing.value=false}
}
function referenceFileChange(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';void chooseReferenceFile(file)}
function referenceDrop(event:DragEvent){event.preventDefault();void chooseReferenceFile(event.dataTransfer?.files[0])}
function referencePaste(event:ClipboardEvent){const file=Array.from(event.clipboardData?.items??[]).find(item=>item.kind==='file')?.getAsFile();if(file){event.preventDefault();void chooseReferenceFile(file)}}
function scopeMatches(scope:WorkbenchReferenceScope,target:unknown,source:object|null){return referencesOpen.value&&referenceTarget.value===target&&selection.currentSource===source&&!!referenceIdentity.value&&workbenchReferenceScopeKey(referenceIdentity.value)===workbenchReferenceScopeKey(scope)}
function attachReference(record:WorkbenchReferenceUpload){
 if(!referenceWritable.value||!referenceIdentity.value||workbenchReferenceScopeKey(record)!==workbenchReferenceScopeKey(referenceIdentity.value)||!record.receipt)return
 const refs=shownReferences.value;if(refs.length>=4){referenceError.value='每层最多 4 张参考图。';return}if(refs.some(ref=>ref.sha256===record.receipt!.sha256)){referenceError.value='该规范化图片已在本层关联。';return}
 refs.push({name:record.name,relativePath:record.receipt.relativePath,sha256:record.receipt.sha256});referenceError.value='文件已上传，仅关联到本层草稿；还需保存并回读工作台。未作为生成输入。'
}
async function uploadReference(){
 const prepared=referenceSelected.value,scope=referenceIdentity.value,upload=aiReferenceUploadProvider.value,target=referenceTarget.value,source=selection.currentSource
 if(!referenceCanUpload.value||!prepared||!scope||!upload)return
 referenceConfirmed.value=false;referenceUploading.value=true
 const record:WorkbenchReferenceUpload={...scope,name:referenceFileName.value,originalSha256:prepared.sha256,mimeType:prepared.mimeType,width:prepared.width,height:prepared.height,receipt:null}
 try{
  const previous=readWorkbenchReferenceUploads(referenceStorage()).find(row=>row.projectId===scope.projectId&&row.projectPath===scope.projectPath&&row.originalSha256===prepared.sha256)
  if(previous&&!previous.receipt||legacyWorkbenchUploadUnknown(referenceStorage(),scope.projectId,prepared.sha256))throw Error('此文件已有未知上传，未重新发送。')
  // A known successful file can be explicitly associated with another layer without uploading its bytes again.
  if(previous?.receipt){record.receipt=previous.receipt;rememberWorkbenchReferenceUpload(referenceStorage(),record)}
  else{
   rememberWorkbenchReferenceUpload(referenceStorage(),record)
   const result=await upload.uploadReference(scope.projectId,{base64:prepared.base64,approved:true})
   record.receipt=decodeAiReferenceUploadReceipt(result,{sha256:prepared.sha256,mimeType:prepared.mimeType,width:prepared.width,height:prepared.height})
   rememberWorkbenchReferenceUpload(referenceStorage(),record)
  }
  if(scopeMatches(scope,target,source)&&upload===aiReferenceUploadProvider.value){loadReferenceRecords();attachReference(record);referenceSelected.value=null;referenceLocalShown.value=false}
  else{referenceError.value='已保留原工程、原层和目标的上传回执；回到原位置后可明确恢复关联。'}
 }catch(error){
  if(error instanceof AiReferenceUploadError&&error.outcome!=='unknown'){
   try{releaseRejectedWorkbenchReferenceUpload(referenceStorage(),record)}catch{referenceStorageBlocked.value=true}
   referenceError.value=error.message+' 未自动重发；原输入保留，可核对后明确重试。'
  }else referenceError.value='上传结果需核对，原工程和原层记录已保留，未自动重发。'+(error instanceof Error?error.message:'')
  if(scopeMatches(scope,target,source)){loadReferenceRecords();if(!(error instanceof AiReferenceUploadError&&error.outcome!=='unknown'))referenceStorageBlocked.value=true}
 }finally{referenceUploading.value=false}
}
function removeReference(index:number){if(referenceWritable.value&&!referenceUploading.value){shownReferences.value.splice(index,1);referencePreview.value=null;referenceError.value='仅移除本层草稿关联，磁盘原文件保留；请保存并回读工作台。'}}
async function previewReference(reference:WorkbenchReference){
 const reader=aiResourceReadProvider.value,scope=referenceIdentity.value,source=selection.currentSource,target=referenceTarget.value
 if(!reader||reader.referencePreviewEnabled===false||!scope)return
 const token=++referencePreviewEpoch;referencePreview.value=null;referencePreviewBusy.value=true;referenceError.value=''
 try{const result=await reader.previewReference(scope.projectId,reference.relativePath);if(token!==referencePreviewEpoch||!scopeMatches(scope,target,source)||reader!==aiResourceReadProvider.value)return;if(result.sha256!==reference.sha256)throw Error('参考图内容哈希已变化，未展示。');referencePreview.value=result}catch(error){if(token===referencePreviewEpoch)referenceError.value=error instanceof Error?error.message:'参考图预览读取失败。'}finally{if(token===referencePreviewEpoch)referencePreviewBusy.value=false}
}

</script>
<template>
 <section class="workbench-manager" data-testid="art-workbench-manager">
  <div class="manager-actions"><button :disabled="!store.context||store.busy||store.dirty" @click="store.read()">读取 / 刷新工作台</button><button v-if="store.phase==='ready'&&!store.draft" :disabled="!norm" @click="norm&&store.initialize(norm)">使用已保存规范初始化</button><button :disabled="!editable||!store.dirty||!norm" @click="store.save()">保存并回读</button><button v-if="store.phase==='unknown'||store.phase==='error'" :disabled="store.busy" @click="store.read(true)">重新核对服务器结果</button><button :disabled="!selection.project||!aiJobsReadProvider" @click="browseJobs">查看现有真实任务</button><span v-if="store.dirty">有未保存修改</span></div>
  <p v-if="store.busy" role="status">{{ store.phase==='saving'?'正在保存并回读…':'正在读取工作台…' }}</p><p v-if="store.error" role="alert">{{ store.error }}</p><p v-if="message" role="alert">{{ message }}</p>
  <p v-if="!norm" role="status">请先在项目规范中读取并保存有效规范。</p><p v-if="store.draft&&norm&&store.draft.norm.hash!==norm.hash" class="review-notice" role="status">项目规范已更新，现有需求需核对；保留原规格快照和已绑定任务。</p>
  <template v-if="store.draft">
   <div class="manager-actions"><label>搜索<input v-model="query" placeholder="名称或标识"></label><label>类别<select v-model="filter"><option value="">全部类别</option><option v-for="category in ART_CATEGORIES" :value="category" :key="category">{{ workbenchLabels[category] }}</option></select></label><button v-if="view==='specs'" :disabled="!editable" @click="newSpec()">新建规格</button><button v-else :disabled="!editable||!store.draft.specs.length" @click="newNeed()">新建需求</button><button @click="references('project')">项目参考 · {{ store.draft.projectReferences.length }}</button></div>
   <div class="table-scroll"><table v-if="view==='specs'"><thead><tr><th>规格 / 类别</th><th>尺寸策略</th><th>宽 × 高</th><th>资源 / 导出目录</th><th>版本 / 参考</th><th>操作</th></tr></thead><tbody><tr v-for="spec in specs" :key="spec.id"><td>{{ spec.name }}<small>{{ workbenchLabels[spec.category] }} · {{ spec.id }}</small></td><td>{{ spec.sizePolicy==='fixed'?'固定尺寸':'每项尺寸（UI）' }}</td><td>{{ spec.width }} × {{ spec.height }}</td><td>{{ spec.destination }}<small>{{ spec.exportDirectory }}</small></td><td>v{{ spec.version }} · {{ spec.references.length }} 张</td><td><button :disabled="!editable" @click="newSpec(spec)">编辑</button></td></tr><tr v-if="!specs.length"><td colspan="6">尚无匹配规格，请新建。</td></tr></tbody></table>
   <table v-else><thead><tr><th>需求 / 类别</th><th>规格快照</th><th>输出尺寸</th><th>真实任务</th><th>操作</th></tr></thead><tbody><tr v-for="need in needs" :key="need.id"><td>{{ need.name }}<small>{{ workbenchLabels[need.spec.category] }} · {{ need.id }}</small></td><td>{{ need.spec.name }} · v{{ need.specVersion }}<small v-if="needsReview(store.draft,need,norm)" class="review-notice">需核对上游更新</small></td><td>{{ needOutputSize(need).width }} × {{ needOutputSize(need).height }}</td><td>{{ need.jobId?'已关联既有任务 · '+need.jobId:'未绑定任务' }}</td><td><button :disabled="!editable||!!need.jobId" @click="newNeed(need)">编辑</button><button v-if="!need.jobId" :disabled="!editable||store.dirty||!store.capabilities?.existingJobLink||!aiJobsReadProvider" @click="openBinding(need)">绑定现有任务</button><button v-else @click="openJob(need)">查看任务</button><button v-if="!need.jobId&&store.draft.specs.find(s=>s.id===need.specId)?.version!==need.specVersion" :disabled="!editable" @click="reviewNeed(need)">核对并采用新规格</button></td></tr><tr v-if="!needs.length"><td colspan="5">尚无匹配需求，请先建立规格。</td></tr></tbody></table></div>
   <p class="form-help">{{ view==='specs'?'项目规范 → 规格范例 → 单素材内容参考逐层说明来源。保存规格不会覆盖已有需求快照。':'这里只绑定已有真实任务。人物、UI 和图片参考条件生成尚未接通。' }}</p>
  </template>
  <section v-if="activeNeed||browsingJobs" class="linked-task"><header class="manager-actions"><h3>{{ activeNeed?activeNeed.name+' · '+activeNeed.jobId:'现有真实任务' }}</h3><button @click="closeJob">返回需求</button></header><p v-if="store.draft&&activeNeed&&needsReview(store.draft,activeNeed,norm)" role="status" class="review-notice">上游已变化，以下保留原任务结果，请核对原快照。</p><p v-if="activeNeed">已关联既有任务，技术参数已核对；新规格的画风和参考图语义未参与历史生成。</p><AiJobsReadPanel :key="activeNeed?.jobId??'existing'" ref="jobsPanel" compact :project="selection.project" :source="selection.currentSource" :workflow-step="taskStep===3?4:taskStep===4?5:6"/></section>
  <el-dialog :model-value="!!specEditor" title="规格" width="760px" @close="specEditor=null"><form v-if="specEditor" class="editor-grid" @submit.prevent="saveSpec"><label>规格标识<input v-model="specEditor.id" :readonly="!!originalId" required></label><label>规格名称<input v-model="specEditor.name" required></label><label>类别<select v-model="specEditor.category" @change="specEditor.category!=='ui'&&(specEditor.sizePolicy='fixed')"><option v-for="category in ART_CATEGORIES" :key="category" :value="category">{{ workbenchLabels[category] }}</option></select></label><label>尺寸策略<select v-model="specEditor.sizePolicy"><option value="fixed">固定尺寸</option><option value="per-asset" :disabled="specEditor.category!=='ui'">每项尺寸（仅 UI）</option></select></label><p v-if="!originalId" class="wide">初始尺寸 128 × 128 为示例，可修改；请按本项目实际要求确认后保存。</p><label>{{ specEditor.sizePolicy==='fixed'?'固定':'推荐' }}宽<input v-model.number="specEditor.width" type="number" min="1" max="4096" required></label><label>{{ specEditor.sizePolicy==='fixed'?'固定':'推荐' }}高<input v-model.number="specEditor.height" type="number" min="1" max="4096" required></label><label>Creator 资源目录<input v-model="specEditor.destination" required></label><label>导出目录<input v-model="specEditor.exportDirectory" required></label><label class="wide">规格画风补充<textarea v-model="specEditor.style" rows="3"/></label><p>透明 PNG · 规格 v{{ specEditor.version }} · 保存后已有需求需核对，原任务保留。</p><button type="button" @click="references('spec')">规格参考 · {{ specEditor.references.length }}</button><p v-if="message" role="alert">{{ message }}</p><div class="manager-actions wide"><button type="button" @click="specEditor=null">取消</button><button type="submit" :disabled="!editable">采用到工作台草稿</button></div></form></el-dialog>
  <el-dialog :model-value="!!needEditor" title="素材需求" width="760px" @close="needEditor=null"><form v-if="needEditor" class="editor-grid" @submit.prevent="saveNeed"><label>需求标识<input v-model="needEditor.id" :readonly="!!originalId" required></label><label>需求名称<input v-model="needEditor.name" required></label><label>类别<select v-model="needCategory" :disabled="!!originalId" @change="needEditor.specId=''"><option v-for="category in ART_CATEGORIES" :key="category" :value="category">{{ workbenchLabels[category] }}</option></select></label><label>继承规格<select :value="needEditor.specId" :disabled="!!originalId" required @change="chooseSpec(($event.target as HTMLSelectElement).value)"><option value="">选择规格</option><option v-for="spec in selectedSpecs" :key="spec.id" :value="spec.id">{{ spec.name }} · v{{ spec.version }}</option></select></label><fieldset v-if="needEditor.specId" class="wide"><legend>继承规格 · 只读</legend><p>{{ needEditor.spec.name }} v{{ needEditor.specVersion }} · {{ needEditor.spec.sizePolicy==='fixed'?'固定尺寸，不可修改':'每项尺寸，可使用推荐值或自定尺寸' }}</p><p>{{ needEditor.spec.width }} × {{ needEditor.spec.height }} · 透明 PNG</p><p>{{ needEditor.spec.destination }} → {{ needEditor.spec.exportDirectory }}</p><p>{{ needEditor.spec.style||'沿用项目画风' }}</p></fieldset><template v-if="needEditor.specId&&needEditor.spec.sizePolicy==='per-asset'&&needEditor.size"><label>本项宽<input v-model.number="needEditor.size.width" type="number" min="1" max="4096" required :readonly="!!needEditor.jobId"></label><label>本项高<input v-model.number="needEditor.size.height" type="number" min="1" max="4096" required :readonly="!!needEditor.jobId"></label></template><label class="wide">内容要求<textarea v-model="needEditor.content" rows="4" required maxlength="4096"/></label><button type="button" @click="references('asset')">单素材参考 · {{ needEditor.references.length }}</button><p v-if="needEditor.jobId">已绑定任务的尺寸和规格快照保持原值。内容修改不会改写原任务。</p><p v-if="message" role="alert">{{ message }}</p><div class="manager-actions wide"><button type="button" @click="needEditor=null">取消</button><button type="submit" :disabled="!editable">采用到工作台草稿</button></div></form></el-dialog>
  <el-dialog v-model="referencesOpen" title="参考来源" width="720px"><section class="reference-editor" @paste="referencePaste"><p>{{ referenceScope }}</p><p>文件上传后只关联本层草稿，还需保存并回读工作台；上传与保存均不代表作为生成输入。人物、UI 和参考图条件生成仍未接通。</p><p v-if="!referenceIdentity" role="status">请先填写当前规格或需求的有效标识，再选择参考图。</p><p v-if="!referenceWritable&&referenceIdentity" role="status">当前工作台或目标不可编辑，已有引用可查看。</p><ul v-if="shownReferences.length"><li v-for="(reference,index) in shownReferences" :key="reference.sha256"><strong>{{ reference.name }}</strong><small>{{ reference.relativePath }} · SHA-256 {{ reference.sha256 }}</small><button :disabled="!aiResourceReadProvider||aiResourceReadProvider.referencePreviewEnabled===false||referencePreviewBusy" @click="previewReference(reference)">预览真实参考</button><button :disabled="!referenceWritable||referenceUploading" @click="removeReference(index)">移除草稿关联</button></li></ul><p v-else>此层尚未关联参考图。</p><div class="reference-drop" @dragover.prevent @drop="referenceDrop" tabindex="0"><label>选择 / 拖入 / 粘贴静态 PNG、JPEG 或 WebP（每张不超过 4 MiB，每层最多 4 张）<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="!referenceWritable||!aiReferenceUploadProvider||!store.capabilities?.referenceUpload||referencePreparing||referenceUploading" @change="referenceFileChange"></label></div><p v-if="!aiReferenceUploadProvider||!store.capabilities?.referenceUpload" role="status">当前未接通上传服务，请核对后台配置；不会发送文件。</p><p v-if="referencePreparing" role="status">正在本地解码和校验文件…</p><div v-if="referenceSelected"><img class="reference-preview" :src="referenceLocalUrl" :alt="'本地预览：'+referenceFileName" @load="referenceLocalShown=true" @error="referenceLocalShown=false;referenceError='本地预览显示失败，已禁止上传。'"><p>{{ referenceFileName }} · {{ referenceSelected.width }} × {{ referenceSelected.height }}</p><label><input v-model="referenceConfirmed" type="checkbox" :disabled="!referenceLocalShown||referenceUploading">确认向当前工程上传此文件并关联本层草稿</label><button :disabled="!referenceCanUpload" @click="uploadReference">上传并关联本层草稿</button></div><p v-if="referenceUploading" role="status">正在上传文件，工作台引用尚未保存…</p><p v-if="referenceError" role="alert">{{ referenceError }}</p><p v-if="referencePreviewBusy" role="status">正在核对真实参考图…</p><img v-if="referencePreview" class="reference-preview" :src="'data:image/png;base64,'+referencePreview.base64" alt="经哈希核对的工程参考图" @error="referencePreview=null;referenceError='参考图显示失败，未放宽安全策略。'"><details v-if="scopeRecords.length"><summary>原层上传恢复记录</summary><div v-for="record in scopeRecords" :key="record.originalSha256"><p>{{ record.name }} · {{ record.scope }} / {{ record.targetId }} · 原图 SHA {{ record.originalSha256 }}</p><template v-if="record.receipt"><p>{{ record.receipt.relativePath }}</p><button :disabled="!referenceWritable||referenceUploading||shownReferences.some(ref=>ref.sha256===record.receipt?.sha256)" @click="attachReference(record)">明确恢复到本层草稿</button></template><p v-else>上传结果未知，文件可能已落盘；禁止重传，请核对原工程文件和回执。</p></div></details><button @click="referencesOpen=false;emit('open-references')">前往参考素材采集</button></section></el-dialog>
  <el-dialog :model-value="!!binding" title="绑定现有真实任务" width="700px" @close="binding=null"><p>绑定仅关联已有 jobId；保存时核对规范哈希、类别、素材标识、尺寸和目录等技术参数。新规格的画风和参考图语义未参与历史生成。</p><p v-if="jobsBusy" role="status">正在回读真实任务…</p><p v-if="message" role="alert">{{ message }}</p><label>任务<select v-model="jobId" :disabled="jobsBusy||!!binding?.jobId"><option value="">选择现有任务</option><option v-for="job in jobs" :key="job.jobId" :value="job.jobId">{{ job.jobId }} · {{ job.state }}{{ job.historyOnly?' · 历史只读':'' }}</option></select></label><p v-if="!jobsBusy&&!jobs.length">当前没有可绑定的已读取任务。</p><button :disabled="jobsBusy||!jobId||store.busy||!!binding?.jobId" @click="bindJob">保存绑定并回读</button></el-dialog>
 </section>
</template>
